    public void testValidateSubType_IllegalClassNameInSet() throws Exception {
        String illegalName = "com.example.BadClass";
        injectIllegalClassName(illegalName);

        JavaType type = typeFactory.constructType(createMockClass(illegalName));

        try {
            validator.validateSubType(ctxt, type);
            org.junit.Assert.fail("Expected JsonMappingException was not thrown");
        } catch (JsonMappingException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Illegal type (" + illegalName + ")"));
        }
    }

